UPDATE mcp_server
SET status = #{status},
    lock_version = lock_version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND status = #{expectedStatus}

UPDATE mcp_server
SET sync_status = 'FAILED',
    last_error_code = #{errorCode},
    last_error_summary = #{errorSummary},
    updated_at = #{now}
WHERE id = #{id}
